:root {
  --card-bg: #e8f4f8;
  --header-bg: #1a6b8a;
  --header-text: #ffffff;
  --badge-bg: #f0a500;
  --badge-text: #1a1a1a;
  --high-bg: #d0eaf5;
  --low-bg: #fef3cc;
  --high-accent: #1a6b8a;
  --low-accent: #c07a00;
  --label-text: #444444;
  --height-text: #111111;
  --footer-bg: #1a6b8a;
  --footer-text: #cce9f5;
  --border-color: #a8d4e8;
}

.tide-card {
  background-color: var(--card-bg);
  border: 2px solid var(--border-color);
  border-radius: 14px;
  width: 340px;
  overflow: hidden;
}

.tide-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.tide-icon {
  font-size: 22px;
}

.tide-title {
  flex: 1;
}

.tide-title h2 {
  color: var(--header-text);
  font-size: 16px;
  font-weight: 700;
  margin: 0;
  line-height: 1.2;
}

.tide-date {
  color: var(--footer-text);
  font-size: 12px;
  margin: 0;
  line-height: 1.4;
}

.tide-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
}

.tide-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 14px;
}

.tide-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 8px;
  border-left: 4px solid;
}

.tide-row.high {
  background-color: var(--high-bg);
  border-left-color: var(--high-accent);
}

.tide-row.low {
  background-color: var(--low-bg);
  border-left-color: var(--low-accent);
}

.tide-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--label-text);
  flex: 1;
}

.tide-time {
  font-size: 13px;
  color: var(--label-text);
}

.tide-height {
  font-size: 14px;
  font-weight: 700;
  color: var(--height-text);
  min-width: 40px;
  text-align: right;
}

.tide-footer {
  background-color: var(--footer-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
}

.moon-phase {
  color: var(--header-text);
  font-size: 13px;
  font-weight: 600;
}

.tide-note {
  color: var(--footer-text);
  font-size: 11px;
}
